import React, { useState } from 'react';

function Chatbot() {
  const [open, setOpen] = useState(false);
  const chatbotUrl = "https://agent.jotform.com/019902f7bce27a5e85010e43b3d62d4bdce4";

  return (
    <>
      {/* Floating button to open chatbot */}
      <button
        className="chatbot-toggle-btn"
        onClick={() => setOpen(!open)}
        aria-label={open ? 'Close chatbot' : 'Open chatbot'}
      >
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
          <circle cx="12" cy="12" r="10" fill="#0a192f" />
          <path d="M7 10h10M7 14h6" stroke="#64ffda" strokeWidth="2" strokeLinecap="round" />
        </svg>
      </button>
      {open && (
        <div className="chatbot-container">
          <iframe
            src={chatbotUrl}
            title="JotForm Chatbot"
            width="360"
            height="520"
            frameBorder="0"
            allowFullScreen
          />
        </div>
      )}
    </>
  );
}

export default Chatbot;
